"use client";

import { useState, useEffect, useRef } from "react";
import { getPlaceholderImage } from "@/lib/image-utils";
import { Package } from "lucide-react";
import { useProductStore } from "@/store/product-store";

interface SafeImageProps {
  src: string | null | undefined;
  alt: string;
  fill?: boolean;
  width?: number;
  height?: number;
  className?: string;
  priority?: boolean;
  loading?: "lazy" | "eager";
  sizes?: string;
  onError?: () => void;
  placeholder?: "blur" | "empty";
  blurDataURL?: string;
  productId?: string;
}

/**
 * کامپوننت SafeImage ساده و قابل اعتماد
 * فقط از img tag استفاده می‌کند و retry ساده دارد
 */
export function SafeImage({
  src,
  alt,
  fill = false,
  width,
  height,
  className = "",
  priority = false,
  loading = "eager",
  sizes,
  onError,
  placeholder = "empty",
  blurDataURL,
  productId,
}: SafeImageProps) {
  const getProduct = useProductStore((state) => state.getProduct);
  const placeholderUrl = getPlaceholderImage(width || 600, height || 600);
  
  // دریافت URL تصویر
  const getImageUrl = (): string => {
    // 1. از src prop
    if (src && typeof src === 'string' && src.trim() !== '') {
      return src.trim();
    }
    
    // 2. از product store
    if (productId) {
      const product = getProduct(productId);
      if (product?.images && Array.isArray(product.images) && product.images.length > 0) {
        const firstImage = product.images[0];
        if (firstImage && typeof firstImage === 'string' && firstImage.trim() !== '') {
          return firstImage.trim();
        }
      }
    }
    
    return placeholderUrl;
  };

  const [imageSrc, setImageSrc] = useState<string>(() => getImageUrl());
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const imgRef = useRef<HTMLImageElement>(null);
  const retryCountRef = useRef(0);
  const maxRetries = 3;

  // Update image source when props change
  useEffect(() => {
    const url = getImageUrl();
    setImageSrc(url);
    setIsLoading(true);
    setHasError(false);
    retryCountRef.current = 0;
  }, [src, productId, width, height, getProduct]);

  const handleLoad = () => {
    setIsLoading(false);
    setHasError(false);
  };

  const handleError = () => {
    const currentUrl = getImageUrl();
    
    // اگر placeholder است، دیگر retry نکن
    if (currentUrl === placeholderUrl) {
      setIsLoading(false);
      setHasError(true);
      onError?.();
      return;
    }

    // Retry logic
    if (retryCountRef.current < maxRetries) {
      retryCountRef.current += 1;
      
      // Retry با timestamp
      const separator = currentUrl.includes('?') ? '&' : '?';
      const retryUrl = `${currentUrl}${separator}_retry=${retryCountRef.current}&_t=${Date.now()}`;
      
      setTimeout(() => {
        if (imgRef.current) {
          imgRef.current.src = retryUrl;
        }
      }, 1000 * retryCountRef.current);
    } else {
      // اگر همه retry ها ناموفق بودند
      setIsLoading(false);
      setHasError(true);
      
      // از product store fallback کن
      if (productId) {
        const product = getProduct(productId);
        if (product?.images && Array.isArray(product.images) && product.images.length > 0) {
          const fallbackImage = product.images.find(
            img => img && typeof img === 'string' && img.trim() !== '' && img !== currentUrl
          );
          if (fallbackImage) {
            retryCountRef.current = 0;
            setImageSrc(fallbackImage.trim());
            setIsLoading(true);
            return;
          }
        }
      }
      
      // در آخر placeholder
      setImageSrc(placeholderUrl);
      onError?.();
    }
  };

  // مطمئن شو که imageSrc هرگز empty string نباشد
  const finalSrc = imageSrc || placeholderUrl;

  const imgProps: React.ImgHTMLAttributes<HTMLImageElement> = {
    src: finalSrc,
    alt,
    onLoad: handleLoad,
    onError: handleError,
    loading: loading,
    className: "object-cover w-full h-full",
    style: { objectFit: 'cover' },
    fetchPriority: priority ? 'high' : 'auto',
    decoding: 'async',
  };

  if (fill) {
    return (
      <div className={`relative ${className}`} style={{ width: '100%', height: '100%' }}>
        <img {...imgProps} ref={imgRef} />
        {isLoading && !hasError && (
          <div className="absolute inset-0 bg-muted animate-pulse flex items-center justify-center z-10">
            <Package className="h-8 w-8 text-muted-foreground" />
          </div>
        )}
      </div>
    );
  }
  
  return (
    <div className={`relative ${className}`} style={{ width, height }}>
      <img {...imgProps} ref={imgRef} />
      {isLoading && !hasError && (
        <div className="absolute inset-0 bg-muted animate-pulse flex items-center justify-center z-10">
          <Package className="h-8 w-8 text-muted-foreground" />
        </div>
      )}
    </div>
  );
}
